import { useId } from 'react'

// The shelf mark: the series is the shelf; on it two books stand and two lie in an indented stack.
// Spine bands are cut out with a mask. Geometry is shared with public/favicon.svg and public/mythos-logo*.svg
// (generated by logo-alternatives/build_public.py); change them together.
interface Book {
  x: number
  y: number
  width: number
  height: number
  rx: number
  transform?: string
}

const SHELF_AND_BOOKS: readonly Book[] = [
  { x: 48, y: 396, width: 416, height: 72, rx: 20 },
  { x: 72, y: 104, width: 84, height: 268, rx: 18 },
  { x: 176, y: 148, width: 84, height: 224, rx: 18 },
  { x: 280, y: 290, width: 184, height: 82, rx: 18 },
  { x: 300, y: 200, width: 148, height: 74, rx: 18, transform: 'rotate(-6 300 274)' },
]
const BANDS = 'M96 168H132M200 212H236M420 312V340M400 226V254'

// Monochrome; inherits the brand colour via currentColor so it flips with the theme.
interface LogoProps {
  className?: string
}

export default function Logo({ className = 'mark' }: LogoProps) {
  const maskId = `mythos-bands-${useId()}`
  return (
    <svg className={className} viewBox="0 0 512 512" fill="none" aria-hidden="true">
      <defs>
        <mask id={maskId} maskUnits="userSpaceOnUse" x="0" y="0" width="512" height="512">
          <rect width="512" height="512" fill="#fff" />
          <path d={BANDS} stroke="#000" strokeWidth="16" strokeLinecap="round" />
        </mask>
      </defs>
      <g fill="currentColor" mask={`url(#${maskId})`}>
        {SHELF_AND_BOOKS.map((book) => <rect key={`${book.x}-${book.y}`} {...book} />)}
      </g>
    </svg>
  )
}
